#
# [931] 下降路径最小和
#

# @lc code=start
from typing import List

class Solution:
    def minFallingPathSum(self, matrix: List[List[int]]) -> int:
        m, n = len(matrix), len(matrix[0])
        dp = [[float('inf')] * n for _ in  range(m)]

        for i in range(m):
            for j in range(n):
                if i == 0:
                    dp[i][j] = matrix[i][j]
                    continue

                if j < n-1:
                    dp[i][j] = min(dp[i-1][j+1], dp[i-1][j], dp[i][j])

                if j > 0:
                    dp[i][j] = min(dp[i-1][j-1], dp[i-1][j], dp[i][j])

                dp[i][j] += matrix[i][j]
        return min(dp[-1])



